// https://storybook.js.org/docs/7.0/preact/writing-stories/introduction
import type { Meta, StoryObj } from '@storybook/preact-vite';
import {
  CartList as component,
  CartListProps,
  CartItem,
  Image,
  Price,
} from '@adobe-commerce/elsie/components';

/**
 * Use CartList to display a list of product items in Cart.
 */
const meta: Meta<CartListProps> = {
  title: 'Components/CartList',
  component,
  parameters: {
    layout: 'padded', // centered | fullscreen
  },
  argTypes: {
    children: {
      control: {
        type: 'select',
        labels: {
          Products5: '5 Products',
          Products3: '3 Products',
          Products1: '1 Product',
        },
      },
      description: 'Items in the list.',
      options: ['Products5', 'Products3', 'Products1'],
      mapping: {
        Products5: renderItems(5),
        Products3: renderItems(3),
        Products1: renderItems(1),
      },
      table: { defaultValue: { summary: 'null' } },
    },
  },
};

export default meta;

type Story = StoryObj<CartListProps>;

/**
 * ```tsx
 * <CartList>
 *  <CartItem .../>
 * </CartList>
 * ```
 */
export const CartList: Story = {
  args: {
    children: 'Products5' as any,
  },
  // Flaky storybook smoke test
  tags: ['skip'],
};

export const WithPromotionalBadges: Story = {
  args: {
    children: renderItemsWithPromos(3),
  },
};

function renderItems(count: number) {
  return Array.from({ length: count }, (_, i) => i + 1).map((key) => (
    <CartItem
      key={key}
      image={
        <Image
          src="https://picsum.photos/132/184"
          width="132"
          height="184"
          alt="Some alternative text"
          loading="lazy"
        />
      }
      title={<div>Product Name</div>}
      description={
        <div>
          Secondary product information such as brand name, description, etc.
        </div>
      }
      sku={<div>SKU: 59YK7</div>}
      quantity={1}
      price={
        <span>
          <Price
            amount={53.99}
            style={{ fontWeight: 'inherit', color: 'inherit' }}
          />
        </span>
      }
      total={
        <span>
          <Price amount={59.98} variant="strikethrough" />{' '}
          <Price amount={55.95} sale />
        </span>
      }
      configurations={{ Color: 'Blue', Size: 'L' }}
      onRemove={() => {}}
      onQuantity={() => {}}
      taxIncluded={true}
    />
  ));
}

function renderItemsWithPromos(count: number) {
  return Array.from({ length: count }, (_, i) => i + 1).map((key) => {
    // Show promo badge on first and third items as an example
    const showPromo = key === 1 || key === 3;

    return (
      <CartItem
        key={key}
        image={
          <Image
            src="https://picsum.photos/132/184"
            width="132"
            height="184"
            alt="Some alternative text"
            loading="lazy"
          />
        }
        title={<div>Product Name {key}</div>}
        description={
          <div>
            Secondary product information such as brand name, description, etc.
          </div>
        }
        sku={<div>SKU: 59YK{key}</div>}
        quantity={1}
        price={
          <span>
            <Price
              amount={53.99}
              style={{ fontWeight: 'inherit', color: 'inherit' }}
            />
          </span>
        }
        rowTotalFooter={
          showPromo ? (
            <div
              style={{ color: 'var(--color-alert-800)', fontWeight: 'bold' }}
            >
              Super offer
            </div>
          ) : undefined
        }
        total={
          <span>
            <Price amount={59.98} variant="strikethrough" />{' '}
            <Price amount={55.95} sale />
          </span>
        }
        configurations={{ Color: 'Blue', Size: 'L' }}
        onRemove={() => {}}
        onQuantity={() => {}}
        taxIncluded={true}
      />
    );
  });
}
